//! Table tests of a collection behaviour sigmastate keeps below an ACTIVATED script version of 2
//! (`VersionContext.isJitActivated` false): `pairColl` with sides of unequal length. The rows are
//! sigma-state 6.0.7's (the round's `measure/`; generated by `measure/tests2/gen_pre_tests.py`):
//! every measured row that fork `master` `26a9e266` got wrong at activated version 1, its twin at
//! activated version 3, where nothing changes, and the rows of equal sides as controls.
use crate::eval::test_util::{eval_body_at, jvm_text};
use ergotree_ir::ergo_tree::ErgoTreeVersion;

/// A row: its name in the round's row sets (set, name, activated version), the expression's bytes,
/// the tree version, the activated version, the value as `jvm_text` prints it or `ERR`, and the cost
/// counter
type Row = (&'static str, &'static str, u8, i8, &'static str, u64);

/// The rows whose outcome, value or cost counter is not the table's
fn wrong_rows(rows: &[Row]) -> alloc::vec::Vec<alloc::string::String> {
    let mut wrong = alloc::vec::Vec::new();
    for (name, body, version, activated, expected, cost) in rows {
        let (res, stopped_at) = eval_body_at(body, ErgoTreeVersion::from(*version), *activated);
        let got = match &res {
            Ok(v) => jvm_text(v),
            Err(_) => "ERR".into(),
        };
        if got != *expected || stopped_at != *cost {
            wrong.push(alloc::format!(
                "{name}: expected {expected} at {cost}, got {got} at {stopped_at} ({res:?})"
            ));
        }
    }
    wrong
}

